impl Discovery {
    /// Loopback excludes all interfaces before browsing or advertising. A custom
    /// UDP port also avoids touching the workstation's Bonjour service during checks.
    pub fn new(scope: DiscoveryScope, mdns_port: u16) -> Result<Self, NetError> {
        Self::with_browse(scope, mdns_port, true)
    }
    pub(crate) fn with_browse(scope: DiscoveryScope, mdns_port: u16, browse: bool) -> Result<Self, NetError> {
        if mdns_port == 24800 {
            return Err(NetError::ProductionPortDenied);
        }
        let daemon = ServiceDaemon::new_with_port(mdns_port).map_err(failed)?;
        let setup = (|| {
            if scope == DiscoveryScope::Loopback {
                daemon.disable_interface(IfKind::All).map_err(failed)?;
                daemon.enable_interface(IfKind::LoopbackV4).map_err(failed)?;
            }
            let monitor = daemon.monitor().map_err(failed)?;
            let events = if browse {
                Some(daemon.browse_limited(SERVICE_TYPE, 64).map_err(failed)?)
            } else {
                None
            };
            Ok((monitor, events))
        })();
        let (monitor, events) = match setup {
            Ok(v) => v,
            Err(e) => {
                let _ = daemon.shutdown();
                return Err(e);
            }
        };
        Ok(Self {
            daemon,
            events,
            monitor,
            peers: BTreeMap::new(),
            published: None,
            scope,
            dirty: false,
            last_snapshot: Instant::now() - Duration::from_secs(1),

        // Exit already unregisters services and stops browsing on the owned
        // worker. Separate cleanup commands can fail before Exit is submitted
        // (e.g. no descriptor for mdns-sd's temporary command-wake socket).
        self.daemon.shutdown().map_err(failed)?;
        Ok(())
    }
}
impl Drop for Discovery {
    fn drop(&mut self) {
        let _ = self.shutdown();
    }
}

/// [`monitor`](Self::monitor).
pub fn new_with_port(port: u16) -> Result<Self> {
    // Use port 0 to allow the system assign a random available port,
    // no need for a pre-defined port number.
    let signal_addr = SocketAddrV4::new(LOOPBACK_V4, 0);

    let signal_sock = UdpSocket::bind(signal_addr)
        .map_err(|e| e_fmt!("failed to create signal_sock for daemon: {}", e))?;

    // Get the socket with the OS chosen port
    let signal_addr = signal_sock
        .local_addr()
        .map_err(|e| e_fmt!("failed to get signal sock addr: {}", e))?;

    // Must be nonblocking so we can listen to it together with mDNS sockets.
    signal_sock
        .set_nonblocking(true)
        .map_err(|e| e_fmt!("failed to set nonblocking for signal socket: {}", e))?;

    let poller = Poll::new().map_err(|e| e_fmt!("failed to create mio Poll: {e}"))?;

    let (sender, receiver) = bounded(100);

    // Spawn the daemon thread
    let mio_sock = MioUdpSocket::from_std(signal_sock);
    let cmd_sender = sender.clone();
    thread::Builder::new()
        .name("mDNS_daemon".to_string())
        .spawn(move || {
            Self::daemon_thread(mio_sock, poller, receiver, port, cmd_sender, signal_addr)
        })
        .map_err(|e| e_fmt!("thread builder failed to spawn: {}", e))?;

    fn daemon_thread(
        signal_sock: MioUdpSocket,
        poller: Poll,
        receiver: Receiver<Command>,
        port: u16,
        cmd_sender: Sender<Command>,
        signal_addr: SocketAddr,
    ) {
        let mut zc = Zeroconf::new(signal_sock, poller, port, cmd_sender, signal_addr);

        if let Some(cmd) = zc.run(receiver) {
            match cmd {
                Command::Exit(resp_s) => {
                    // It is guaranteed that the receiver already dropped,
                    // i.e. the daemon command channel closed.
                    if let Err(e) = resp_s.send(DaemonStatus::Shutdown) {
                        debug!("exit: failed to send response of shutdown: {}", e);
                    }
                }
                _ => {
                    debug!("Unexpected command: {:?}", cmd);
                }
            }
        }
    }
}

